package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.Participacao;
@WebServlet("/admin/participacoes") public class ParticipacaoServlet extends HttpServlet{private final ParticipacaoDAO dao=new ParticipacaoDAO();private final EstudanteDAO estudanteDAO=new EstudanteDAO();private final AtividadeDAO atividadeDAO=new AtividadeDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{r.setAttribute("participacoes",dao.listar());r.setAttribute("estudantes",estudanteDAO.listarAtivos());r.setAttribute("atividades",atividadeDAO.listar());r.getRequestDispatcher("/WEB-INF/views/admin/participacoes.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
 @Override protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{Long eid=Long.valueOf(r.getParameter("estudanteId")),aid=Long.valueOf(r.getParameter("atividadeId"));String a=r.getParameter("acao");if("excluir".equals(a)){dao.excluir(eid,aid);redir(r,p,"exclusao");return;}Participacao q=new Participacao(eid,aid,r.getParameter("funcao"),r.getParameter("descricaoContribuicao"));if("editar".equals(a))dao.atualizar(q);else{if(dao.existe(eid,aid)){r.setAttribute("erro","erro.participacao.duplicada");doGet(r,p);return;}dao.inserir(q);}redir(r,p,"editar".equals(a)?"alteracao":"cadastro");}catch(NumberFormatException e){r.setAttribute("erro","erro.id.invalido");doGet(r,p);}catch(SQLException e){throw new ServletException("Erro ao processar participação.",e);}}
 private void redir(HttpServletRequest r,HttpServletResponse p,String s)throws IOException{p.sendRedirect(r.getContextPath()+"/admin/participacoes?sucesso="+s);}}
